\question{8}{10} The number of fish in an aquarium is recorded at the end of each day from last Monday to Friday. The table shows the net change in the number of fish on each day. (An increase in the number of fish by the end of a day is represented by a positive number.)

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\textbf{Monday} & \textbf{Tuesday} & \textbf{Wednesday} & \textbf{Thursday} & \textbf{Friday} \\
\hline
$+37$ & $-19$ & $-23$ & $+48$ & $-31$ \\
\hline
\end{tabular}
\end{center}

\begin{subparts}
  \item Find the net change in the number of fish from the beginning of Monday to the end of Friday.

  \item It is known that there were more than $58$ fish in the aquarium at the end of Friday.
  \begin{subpartsii}[1]
    \item Find the least possible number of fish in the aquarium before Monday.
    \item David claims that there must have been more than $50$ fish in the aquarium before Monday. Do you agree? Explain your answer.
  \end{subpartsii}

  \item There were $65$ fish in the aquarium at the end of Wednesday. Find the number of fish in the aquarium by
  \begin{subpartsii}[1]
    \item the end of Friday,
    \item the end of Monday.
  \end{subpartsii}
\end{subparts}

\answerlines{13}

% ============================================================
% ms-q8.tex - Marking scheme for Question 8 (10 marks)
% ============================================================

\msquestion{8}{10}

\begin{center}
\renewcommand{\arraystretch}{1.4}
\begin{tabular}{|c|c|c|c|c|}
\hline
\textbf{Monday} & \textbf{Tuesday} & \textbf{Wednesday} & \textbf{Thursday} & \textbf{Friday} \\
\hline
$+37$ & $-19$ & $-23$ & $+48$ & $-31$ \\
\hline
\end{tabular}
\end{center}

\vspace{4pt}

\begin{mspart}{(a)}
  \msstep{37 + (-19) + (-23) + 48 + (-31) = 12}{1M+1A}
\end{mspart}

\begin{mspart}{(b)}
  \msstep{(i) \ x + 12 > 58 \quad \Rightarrow \quad x > 46}{1M}
  \msstep{\text{Least possible number before Monday} = 47}{1A}
  \msstep{(ii) \ \text{Since the least possible number is } 47, \text{ it is not necessary that } x > 50.}{1M}
  \msstep{\text{No, disagree with David.}}{1A}
\end{mspart}

\begin{mspart}{(c)}
  \msstep{\text{Net change from Monday to Wednesday} = 37 + (-19) + (-23) = -5}{1M}
  \msstep{\text{Number of fish before Monday} = 65 - (-5) = 70}{1M}
  \msstep{(i) \ \text{Number of fish at end of Friday} = 70 + 12 = 82}{1A}
  \msstep{(ii) \ \text{Number of fish at end of Monday} = 70 + 37 = 107}{1M+1A}
\end{mspart}

