\question{6}{8} Answer the following questions.

\begin{subparts}
  \item Find the H.C.F. and L.C.M. of $12$, $18$ and $30$ by using prime factorization.

  \item Given that the five-digit number $518\Delta 3$ is a multiple of $9$ ($\Delta$ is a digit). Find the value of $\Delta$.
\end{subparts}

\answerlines{12}

% ============================================================
% ms-q6.tex - Marking scheme for Question 6 (8 marks)
% ============================================================

\msquestion{6}{8}

\begin{mspart}{(a)}
  \msstep{12 = 2^2 \times 3, \quad 18 = 2 \times 3^2, \quad 30 = 2 \times 3 \times 5}{1M}
  \msstep{\text{H.C.F.} = 2 \times 3 = 6}{1A}
  \msstep{\text{L.C.M.} = 2^2 \times 3^2 \times 5 = 180}{1M+1A}
\end{mspart}

\begin{mspart}{(b)}
  \msstep{5 + 1 + 8 + \Delta + 3 = 17 + \Delta}{1M}
  \msstep{17 + \Delta \text{ is a multiple of } 9}{1M}
  \msstep{\Delta = 1}{1A}
  \msstep{\text{Checking: } 5 + 1 + 8 + 1 + 3 = 18}{1A}
\end{mspart}

