  \msstep{= \left(\dfrac{5}{6} + \dfrac{2}{3}\right) \div \left(\dfrac{3}{4} + \dfrac{1}{4}\right) + \dfrac{1}{3}}{1M}
  \msstep{= \dfrac{3}{2} \div 1 + \dfrac{1}{3} = \dfrac{3}{2} + \dfrac{1}{3}}{1M}
